export type KiltTokenName = keyof typeof kiltTokens;
export type KiltTokenGroup = (typeof kiltTokens)[KiltTokenName]["group"];

/** Prose motion values from cds/guidelines.md; `ms` fields feed JS delay props. */
export const kiltMotion = {
  "duration-exit": { cssVar: "--kilt-duration-exit", value: "120ms", ms: 120 },
  "duration-tooltip-exit": { cssVar: "--kilt-duration-tooltip-exit", value: "110ms", ms: 110 },
  "delay-hover": { cssVar: "--kilt-delay-hover", value: "350ms", ms: 350 },
  "scale-overlay-from": { cssVar: "--kilt-scale-overlay-from", value: "0.97" },
  "scale-dialog-from": { cssVar: "--kilt-scale-dialog-from", value: "0.95" },
  "scale-toast-from": { cssVar: "--kilt-scale-toast-from", value: "0.8" },
  "shift-pane-from": { cssVar: "--kilt-shift-pane-from", value: "4px" },
} as const;

/** A token's CSS var() reference, typed so a typo fails the build. */
export const token = (name: KiltTokenName) => `var(${kiltTokens[name].cssVar})` as const;
